"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useEffect, useState } from "react";
import { ArrowUp, Grid2x2, Heart, Home, ShoppingCart, User } from "lucide-react";
import { cn } from "@/lib/utils";

const TABS = [
  { href: "/", label: "Home", icon: Home, match: (p: string) => p === "/" },
  { href: "/search", label: "Shop", icon: Grid2x2, match: (p: string) => p.startsWith("/search") || p.startsWith("/category") },
  { href: "/account/wishlist", label: "Wishlist", icon: Heart, match: (p: string) => p.startsWith("/account/wishlist") },
  { href: "/cart", label: "Cart", icon: ShoppingCart, match: (p: string) => p.startsWith("/cart") || p.startsWith("/checkout") },
  { href: "/account", label: "Account", icon: User, match: (p: string) => p === "/account" || p.startsWith("/order") },
];

/** App-style bottom tab bar on phones (hidden on product pages, which have their own sticky buy bar). */
export function MobileBottomNav() {
  const path = usePathname();
  if (path.startsWith("/product/")) return null;
  return (
    <nav aria-label="Primary" className="fixed inset-x-0 bottom-0 z-40 border-t border-line bg-white/95 pb-[env(safe-area-inset-bottom)] backdrop-blur md:hidden">
      <ul className="grid grid-cols-5">
        {TABS.map(({ href, label, icon: Icon, match }) => {
          const active = match(path);
          return (
            <li key={href}>
              <Link href={href} className={cn("press flex flex-col items-center gap-0.5 py-2 text-[11px] transition-colors", active ? "font-semibold text-maroon" : "text-ink-soft")} aria-current={active ? "page" : undefined}>
                <Icon className={cn("h-5 w-5 transition-transform duration-300", active && "-translate-y-0.5 scale-110")} aria-hidden />
                {label}
                <span className={cn("h-0.5 w-5 rounded-full bg-maroon transition-all duration-300", active ? "opacity-100" : "w-0 opacity-0")} />
              </Link>
            </li>
          );
        })}
      </ul>
    </nav>
  );
}

export function BackToTop() {
  const [show, setShow] = useState(false);
  useEffect(() => {
    const onScroll = () => setShow(window.scrollY > 900);
    onScroll();
    window.addEventListener("scroll", onScroll, { passive: true });
    return () => window.removeEventListener("scroll", onScroll);
  }, []);
  return (
    <button
      onClick={() => window.scrollTo({ top: 0, behavior: "smooth" })}
      aria-label="Back to top"
      tabIndex={show ? 0 : -1}
      className={cn(
        "press fixed bottom-24 left-5 z-40 flex h-11 w-11 items-center justify-center rounded-full bg-ink text-white shadow-lg transition duration-300 md:bottom-6",
        show ? "translate-y-0 opacity-100" : "pointer-events-none translate-y-4 opacity-0",
      )}
    >
      <ArrowUp className="h-5 w-5" />
    </button>
  );
}
