"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";
import { ShoppingCart } from "lucide-react";

/** Header cart link; the badge bounces whenever the count changes. */
export function CartButton({ count }: { count: number }) {
  const prev = useRef(count);
  const [bump, setBump] = useState(0);
  useEffect(() => {
    if (count !== prev.current) setBump((b) => b + 1);
    prev.current = count;
  }, [count]);
  return (
    <Link href="/cart" className="press relative flex items-center gap-1.5 rounded-md px-2 py-1.5 hover:bg-white/10" aria-label={`Cart, ${count} items`}>
      <ShoppingCart data-cart-target className="h-6 w-6" aria-hidden />
      <span key={bump} className={`absolute -top-0.5 left-5 min-w-5 rounded-full bg-brass px-1 text-center text-xs font-bold text-white ${bump ? "animate-bump" : ""}`}>{count}</span>
      <span className="hidden text-sm font-semibold md:block">Cart</span>
    </Link>
  );
}
