"use client";

import { useEffect, useState } from "react";

/** Rotates announcement messages with a vertical slide; shows all on one line on wide screens. */
export function AnnouncementTicker({ messages }: { messages: string[] }) {
  const [i, setI] = useState(0);
  useEffect(() => {
    if (messages.length < 2 || window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    const t = setInterval(() => setI((x) => (x + 1) % messages.length), 3500);
    return () => clearInterval(t);
  }, [messages.length]);
  return (
    <div className="bg-maroon px-4 text-center text-xs font-medium text-white">
      <p className="hidden py-1.5 lg:block">{messages.join("  ·  ")}</p>
      <div className="relative h-7 overflow-hidden lg:hidden" aria-live="off">
        {messages.map((m, idx) => (
          <p
            key={m}
            className="absolute inset-0 flex items-center justify-center transition-all duration-500 ease-out"
            style={{ transform: `translateY(${(idx - i) * 100}%)`, opacity: idx === i ? 1 : 0 }}
            aria-hidden={idx !== i}
          >
            {m}
          </p>
        ))}
      </div>
    </div>
  );
}
