"use client";

import Image from "next/image";
import Form from "next/form";
import { Clock, Search, Tag } from "lucide-react";
import { useRouter, useSearchParams } from "next/navigation";
import { Suspense, useEffect, useId, useRef, useState } from "react";
import { trackSearch } from "@/app/actions/track";
import { formatINR } from "@/lib/money";
import { cn } from "@/lib/utils";

type Suggest = { products: { name: string; slug: string; price: number; image: string | null }[]; categories: { name: string; slug: string }[] };
type Option = { key: string; href: string; label: string; kind: "product" | "category" | "recent"; price?: number; image?: string | null };
const RECENT_KEY = "sm_recent_searches";

function readRecent(): string[] {
  try {
    const v = JSON.parse(localStorage.getItem(RECENT_KEY) ?? "[]");
    return Array.isArray(v) ? v.slice(0, 5) : [];
  } catch {
    return [];
  }
}

function Highlight({ text, q }: { text: string; q: string }) {
  const i = q ? text.toLowerCase().indexOf(q.toLowerCase()) : -1;
  if (i < 0) return <>{text}</>;
  return <>{text.slice(0, i)}<mark className="bg-transparent font-semibold text-maroon">{text.slice(i, i + q.length)}</mark>{text.slice(i + q.length)}</>;
}

/** Re-mounts the box when the URL query changes so the input mirrors ?q= without syncing state in an effect. */
function KeyedSearchBox() {
  const initial = useSearchParams().get("q") ?? "";
  return <SearchBox key={initial} initial={initial} />;
}

function SearchBox({ initial }: { initial: string }) {
  const router = useRouter();
  const listId = useId();
  const [q, setQ] = useState(initial);
  const [open, setOpen] = useState(false);
  const [data, setData] = useState<Suggest | null>(null);
  const [recent, setRecent] = useState<string[]>([]);
  const [active, setActive] = useState(-1);
  const wrap = useRef<HTMLDivElement>(null);

  // Debounced typeahead fetch; aborts stale requests.
  useEffect(() => {
    const term = q.trim();
    if (term.length < 2) return;
    const ctrl = new AbortController();
    const t = setTimeout(() => {
      fetch(`/api/search/suggest?q=${encodeURIComponent(term.toLowerCase())}`, { signal: ctrl.signal })
        .then((r) => r.json())
        .then((d: Suggest) => { setData(d); setActive(-1); })
        .catch(() => {});
    }, 160);
    return () => { clearTimeout(t); ctrl.abort(); };
  }, [q]);

  useEffect(() => {
    const onDoc = (e: MouseEvent) => { if (!wrap.current?.contains(e.target as Node)) setOpen(false); };
    document.addEventListener("mousedown", onDoc);
    return () => document.removeEventListener("mousedown", onDoc);
  }, []);

  const options: Option[] =
    q.trim().length >= 2 && data
      ? [
          ...data.categories.map((c) => ({ key: `c-${c.slug}`, href: `/category/${c.slug}`, label: c.name, kind: "category" as const })),
          ...data.products.map((p) => ({ key: `p-${p.slug}`, href: `/product/${p.slug}`, label: p.name, kind: "product" as const, price: p.price, image: p.image })),
        ]
      : recent.map((r) => ({ key: `r-${r}`, href: `/search?q=${encodeURIComponent(r)}`, label: r, kind: "recent" as const }));

  const remember = (term: string) => {
    const t = term.trim();
    if (!t) return;
    try { localStorage.setItem(RECENT_KEY, JSON.stringify([t, ...readRecent().filter((x) => x !== t)].slice(0, 5))); } catch {}
    void trackSearch(t).catch(() => {});
  };

  const go = (o: Option) => {
    setOpen(false);
    if (o.kind === "recent") remember(o.label);
    router.push(o.href);
  };

  return (
    <div ref={wrap} className="relative flex w-full min-w-0">
      <input
        name="q"
        value={q}
        onChange={(e) => { setQ(e.target.value); setOpen(true); }}
        onFocus={() => { setRecent(readRecent()); setOpen(true); }}
        onKeyDown={(e) => {
          if (!open || !options.length) return;
          if (e.key === "ArrowDown") { e.preventDefault(); setActive((a) => (a + 1) % options.length); }
          else if (e.key === "ArrowUp") { e.preventDefault(); setActive((a) => (a <= 0 ? options.length - 1 : a - 1)); }
          else if (e.key === "Enter" && active >= 0) { e.preventDefault(); go(options[active]); }
          else if (e.key === "Escape") setOpen(false);
        }}
        placeholder="Search brass kadai, dinner sets, mixer grinders, TVs…"
        aria-label="Search products"
        role="combobox"
        aria-expanded={open && options.length > 0}
        aria-controls={listId}
        aria-activedescendant={active >= 0 ? `${listId}-${active}` : undefined}
        autoComplete="off"
        className="h-11 w-full min-w-0 rounded-l-md border-0 bg-white px-4 text-sm text-ink outline-none transition-shadow placeholder:text-muted focus:ring-2 focus:ring-brass"
        maxLength={80}
      />
      {open && options.length > 0 && (
        <ul id={listId} role="listbox" className="animate-scale-in absolute left-0 right-0 top-[calc(100%+6px)] z-50 origin-top overflow-hidden rounded-lg border border-line bg-white py-1 text-ink shadow-2xl">
          {options[0]?.kind === "recent" && <li className="px-4 pb-1 pt-2 text-xs font-semibold uppercase tracking-wide text-muted">Recent searches</li>}
          {options.map((o, i) => (
            <li key={o.key} id={`${listId}-${i}`} role="option" aria-selected={i === active}>
              <button
                type="button"
                onMouseEnter={() => setActive(i)}
                onClick={() => go(o)}
                className={cn("flex w-full items-center gap-3 px-4 py-2 text-left text-sm transition-colors", i === active ? "bg-paper" : "")}
              >
                {o.kind === "product" ? (
                  <span className="relative h-9 w-9 shrink-0 rounded bg-paper">{o.image && <Image src={o.image} alt="" fill sizes="36px" className="object-contain p-0.5" />}</span>
                ) : o.kind === "category" ? (
                  <Tag className="h-4 w-4 shrink-0 text-brass" aria-hidden />
                ) : (
                  <Clock className="h-4 w-4 shrink-0 text-muted" aria-hidden />
                )}
                <span className="min-w-0 flex-1 truncate">
                  <Highlight text={o.label} q={q.trim()} />
                  {o.kind === "category" && <span className="text-muted"> — category</span>}
                </span>
                {o.price !== undefined && <span className="shrink-0 font-semibold">{formatINR(o.price)}</span>}
              </button>
            </li>
          ))}
          {q.trim().length >= 2 && (
            <li>
              <button type="submit" className="w-full border-t border-line px-4 py-2.5 text-left text-sm font-semibold text-maroon hover:bg-paper">
                See all results for “{q.trim()}” →
              </button>
            </li>
          )}
        </ul>
      )}
    </div>
  );
}

export function SearchBar() {
  return (
    <Form
      action="/search"
      className="flex w-full"
      role="search"
      onSubmit={(e) => {
        const q = new FormData(e.currentTarget).get("q");
        if (typeof q === "string" && q.trim()) {
          try { localStorage.setItem(RECENT_KEY, JSON.stringify([q.trim(), ...readRecent().filter((x) => x !== q.trim())].slice(0, 5))); } catch {}
          void trackSearch(q).catch(() => {});
        }
      }}
    >
      <Suspense fallback={<input name="q" aria-label="Search products" className="h-11 w-full rounded-l-md bg-white px-4 text-sm text-ink" />}>
        <KeyedSearchBox />
      </Suspense>
      <button type="submit" className="press flex h-11 w-12 shrink-0 items-center justify-center rounded-r-md bg-brass text-white hover:brightness-95" aria-label="Search">
        <Search className="h-5 w-5" aria-hidden />
      </button>
    </Form>
  );
}
